args:
f=$(ls *.gpr 2>/dev/null | head -1); if [ -z "$f" ]; then cat > main.gpr <<'EOF'
project Main is
   for Source_Dirs use (".");
   for Object_Dir use "obj";
   for Main use ("main.adb");
end Main;
EOF
f=main.gpr; fi; pkill -f "./main" 2>/dev/null || true; find obj -maxdepth 2 -name '*.lock*' -delete 2>/dev/null || true; gprbuild -P "$f"

f=$(ls *.gpr 2>/dev/null | head -1); if [ -z "$f" ]; then cat > main.gpr <<'EOF'
project Main is
   for Source_Dirs use (".");
   for Object_Dir use "obj";
   for Main use ("main.adb");
end Main;
EOF
f=main.gpr; fi; pkill -f "./main" 2>/dev/null || true; find obj -maxdepth 2 -name '*.lock*' -delete 2>/dev/null || true; gprbuild -P "$f" && exec ./main
